  "implementation": "def solve(case):
    # Validate structure
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if 'segments' not in case or 'budget' not in case:
        raise ValueError("case missing 'segments' or 'budget'")
    segments = case['segments']
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError("segments must be a non-empty list")
    budget = case['budget']
    if not isinstance(budget, int):
        raise ValueError("budget must be an integer")
    for s in segments:
        if not isinstance(s, dict):
            raise ValueError("each segment must be a dict")
        for key in ('name', 'importance', 'minimum', 'capacity'):
            if key not in s or not isinstance(s[key], int):
                raise ValueError(f"segment missing or invalid '{key}'")
    total_min = sum(s['minimum'] for s in segments)
    total_max = sum(s['capacity'] for s in segments)
    if budget < total_min:
        raise ValueError("budget less than sum of minima")
    if budget > total_max:
        raise ValueError("budget exceeds total capacity")
    # Initialize allocations to minima
    allocations = [s['minimum'] for s in segments]
    remaining = budget - total_min
    # Greedy allocation
    while remaining > 0:
        best_idx = None
        best_ratio = -1.0
        for i, s in enumerate(segments):
            if allocations[i] < s['capacity']:
                ratio = s['importance'] / (allocations[i] + 1)
                if ratio > best_ratio:
                    best_ratio = ratio
                    best_idx = i
                # tie-breaking: since we iterate in order, > ensures stable tie-break (first wins)
        if best_idx is None:
            break  # should not happen given budget <= total_max
        allocations[best_idx] += 1
        remaining -= 1
    # Build outputs
    by_name = {segments[i]['name']: allocations[i] for i in range(len(segments))}
    total = sum(allocations)
    return {
        "allocations": allocations,
        "by_name": by_name,
        "total": total
    }"
}
